function reg = patronus_registry()
%PATRONUS_REGISTRY Central dispatch table for objectives and constraint sets.
%   Add a new formulation by adding one line here. Do not edit the main script.

    reg.constraints = containers.Map( ...
        {'1Wing', '1Wing_Nacelle', '2Wings', 'VTOL_2Wings'}, ...
        {@cruise_constraints_2GDL, @cruise_constraints_nacelle, @cruise_constraints_3GDL, @vtolto_path_constraints_3GDL});

    reg.objective = containers.Map( ...
        {'max_range_1W','max_range_2W', 'min_energy_vtol', 'min_time_vtol'}, ...
        {@cruise_objective_max_range_1W, @cruise_objective_max_range_2W, @vtolto_objective_min_energy, @vtolto_objective_min_time});

    % Trajectory segments only

    reg.dynamics = containers.Map( ...
        {'VTOL_2Wings'}, ...
        {@vtolto_dynamics_3GDL});

    % midpoints: the method needs controls at the interval midpoints
    reg.transcription = containers.Map( ...
        {'trapezoidal', 'hermite_simpson'}, ...
        {struct('defects', @collocation_trapezoidal,     'midpoints', false), ...
         struct('defects', @collocation_hermite_simpson, 'midpoints', true)});

    % guess = f(bounds, models, params), [] keeps the guess in the config
    reg.initial_guess = containers.Map( ...
        {'config', 'flat_2Wings'}, ...
        {@(varargin) [], @vtolto_flat_guess_3GDL});

end
